function resultEditor(ex,sid,entry){if(ex.members)return ex.members.map(m=>resultEditor(m,sid,data.entries.find(e=>e.sessionId===sid&&e.exerciseId===m.id))).join('');if(ex.v2){const restored=savedDrafts.take(sid,ex.id);if(restored?.kind==='v2')rich.restore(ex.id,sid,restored.value);return rich.editor(ex,sid,entry,lastFor(ex));}const d=getDraft(ex,sid,entry);const total=d.series.reduce((a,x)=>a+(Number(String(x.kg).replace(',','.'))||0)*(Number(x.reps)||0),0);return `<div class="panel"><h3>${entry?'Popraw wynik':'Nowy wynik'}</h3><form class="seriesResultForm" data-id="${ex.id}" data-session="${sid}"><div class="grid2"><label>Ciężar (kg)<input data-main="kg" inputmode="decimal" value="${esc(d.kg)}" required></label><label>Powtórzenia<input data-main="reps" inputmode="numeric" value="${esc(d.reps)}" required></label></div><div class="series-toolbar"><span class="hint">${d.custom?'Serie zmodyfikowane':'Wynik powielony na '+d.series.length+' serie'}</span><button class="btn" type="button" data-series-toggle="${esc(draftKey(ex.id,sid))}">✎ ${d.open?'Zwiń serie':'Edytuj serie'}</button></div><div class="series-details" ${d.open?'':'hidden'}>${seriesRows(d)}</div><div class="series-total">Tonaż: <strong>${total.toLocaleString('pl-PL')} kg</strong></div><button class="btn primary wide spaced" type="submit">${entry?'Zapisz korektę':'Zapisz wynik'}</button></form></div>`}
